// lib/storage/src/content_manager/toc/mod.rs:407-419 (resolve_name)
fn resolve_name(collection_name: &str, collections: &Collections, aliases: &AliasPersistence) -> Result<String, StorageError> {
    let alias_collection_name = aliases.get(collection_name);
    let resolved_name = match alias_collection_name { None => collection_name.to_string(), Some(resolved_alias) => resolved_alias };
    collections.validate_collection_exists(&resolved_name)?;   // <- unknown name -> StorageError::NotFound -> HTTP 404
    Ok(resolved_name)
}
